import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.D9Xj5MGR.js";const m=JSON.parse('{"title":"Production checklist","description":"","frontmatter":{},"headers":[],"relativePath":"security/production.md","filePath":"security/production.md","lastUpdated":1793730256000}'),r={name:"security/production.md"};function n(s,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="production-checklist" tabindex="-1">Production checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production checklist&quot;">​</a></h1><p>Go through this list before the first deploy, and again when you add instances, Redis, S3 or mail. Each item links to the page that explains it.</p><h2 id="environment-and-keys" tabindex="-1">Environment and keys <a class="header-anchor" href="#environment-and-keys" aria-label="Permalink to &quot;Environment and keys&quot;">​</a></h2><ul><li>[ ] <code>APP_ENV=production</code> (also the default): <code>db:seed</code>, <code>migrate:refresh</code> and <code>migrate:fresh</code> then need <code>--force</code>. <code>migrate:rollback</code> has no such guard: it runs in production as it does elsewhere.</li><li>[ ] <code>APP_DEBUG=false</code>. It is read into <code>app.debug</code>, but the framework does not act on it: internal errors always answer a fixed &quot;Server error.&quot; whatever its value. Your own code may read it.</li><li>[ ] <code>APP_KEY</code> generated once (<code>key:generate --show</code>), stored as a secret, never committed. Rotating it signs every admin out and ends every JWT sign-in (API tokens stay valid). Keep the old key in <code>APP_PREVIOUS_KEYS</code> and run <code>key:reencrypt</code>, then check that <code>key:reencrypt --dry-run</code> exits successfully before removing the old key, or <a href="./../admin/settings.html#secrets">secret settings</a> and <a href="./../digging-deeper/encryption.html">encrypted columns</a> become unreadable (<a href="./../operations/app-key.html">Rotating APP_KEY</a>).</li><li>[ ] Secrets come from the environment or from files (<code>APP_KEY_FILE</code>, <code>DATABASE_URL_FILE</code>, …: <a href="./../getting-started/configuration.html#from-files-docker-and-kubernetes-secrets">secrets from files</a>), not from <code>config/*.toml</code> in the repository.</li><li>[ ] <code>APP_URL</code> is the public <strong>https</strong> URL. It makes session cookies <code>Secure</code> and is the default allowed origin of the admin panel.</li><li>[ ] <code>auth.secure_cookies</code> is unset or <code>true</code>. Never force it to <code>false</code> behind https.</li></ul><h2 id="admin-panel-and-sign-in" tabindex="-1">Admin panel and sign-in <a class="header-anchor" href="#admin-panel-and-sign-in" aria-label="Permalink to &quot;Admin panel and sign-in&quot;">​</a></h2><ul><li>[ ] <code>auth.admin_origins</code> lists every origin serving the admin panel, nothing else (<a href="./authentication.html#csrf">CSRF</a>).</li><li>[ ] <code>http.trusted_proxies</code> lists only your load balancers, so throttling and the audit log see real client IPs (<a href="./../architecture/lifecycle.html#client-ip-and-proxies">Client IP and proxies</a>).</li><li>[ ] <code>auth.jwt.enabled = false</code> when no client uses JWT sign-ins.</li><li>[ ] <code>auth.password_reset = true</code> only with a mail driver configured: boot fails otherwise (<a href="./../digging-deeper/mail.html">Mail</a>).</li><li>[ ] First super admin created with <code>make:user --super-admin</code>; <code>permission:sync</code> run after each deploy.</li><li>[ ] <code>settings.mail.update</code> (SMTP settings, test mails) only for administrators; <code>queue.manage</code> (retry, forget, cancel jobs) and <code>schedules.manage</code> (run a schedule now) only for operators.</li><li>[ ] <a href="./../admin/customizing.html#runtime-branding">Runtime branding</a>: the brand name and logo are public (the sign-in page shows them); only operators may change them; you know the recovery switch (<code>RUSTCMS_ADMIN__BRANDING=static</code>, then restart) if a branding makes the panel unusable.</li></ul><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><ul><li>[ ] Migrations run once per deploy (<code>migrate</code>, then <code>permission:sync</code>), with a backup taken first; you know how to go back: <code>migrate:rollback</code> with the new binary for your migrations, or the old binary with <code>migrate --allow-newer</code> (<a href="./../getting-started/deployment.html#upgrading">Upgrading</a>).</li><li>[ ] MySQL: the database, its tables and <code>sql_mode</code> pass the startup check (<a href="./../basics/database.html#mysql">MySQL</a>).</li><li>[ ] <code>database.max_connections</code> (10 per process) fits the server&#39;s connection limit for every instance and worker process together.</li><li>[ ] Database backups include <code>sessions</code> only if you want sessions to survive restores (<a href="./../operations/backup-restore.html">Backup and restore</a>).</li><li>[ ] <code>audit.retention_days</code> set to what you must keep, no longer: the <a href="./../digging-deeper/audit-log.html">audit log</a> holds personal data (IP addresses, emails typed in failed sign-ins), and so do backups that include it. Restrict who can read <code>audit_logs</code>; ship it elsewhere if it must be tamper-proof. <code>audit.sign_in_failures_per_minute</code> (600) bounds how many failed sign-ins are recorded one by one.</li></ul><h2 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h2><ul><li>[ ] TLS terminates before the app; HTTP redirects to HTTPS at the proxy.</li><li>[ ] <code>http.body_limit</code> (1 MiB) and <code>http.timeout_secs</code> (30) suit your API; the proxy&#39;s request body limit is at least <code>storage.max_upload_bytes</code> (10 MiB) plus 64 KiB (the media upload route accepts that much, for the multipart framing).</li><li>[ ] WebSocket routes (<a href="./../admin/realtime.html#websocket">realtime</a>): the proxy passes <code>Upgrade</code> and allows long-lived connections, and its access and APM logs drop the <code>Sec-WebSocket-Protocol</code> request header (it carries the session&#39;s CSRF token). The <code>[realtime]</code> limits (open streams per instance and per user, opens per minute, message size) suit your traffic (<a href="./../getting-started/configuration.html">Configuration</a>).</li><li>[ ] <code>log.json = true</code> when a log shipper reads the output.</li></ul><h2 id="several-instances-and-workers" tabindex="-1">Several instances and workers <a class="header-anchor" href="#several-instances-and-workers" aria-label="Permalink to &quot;Several instances and workers&quot;">​</a></h2><ul><li>[ ] Several instances: build with the <code>redis</code> feature and set <code>[redis] url</code> (one standalone Redis, one <code>redis.prefix</code> per deployment) so rate limits are shared; the permission cache, the queue and the schedules need nothing (they follow the database). Media storage must be shared (S3, or one volume mounted by every instance). Without Redis, run one instance (<a href="./../digging-deeper/instances.html">Several instances</a>).</li><li>[ ] <a href="./../digging-deeper/instances.html#api-mode">API mode</a> instances (<code>serve --api-only</code>) behind the load balancer: the admin path goes to a <code>full</code> instance; every instance has the same <code>APP_URL</code>, key, storage and <code>trusted_proxies</code>; the pools together fit the database&#39;s connection limit.</li><li>[ ] Password-hashing and upload concurrency limits are per instance (each bounds its own CPU and disk).</li><li>[ ] Queue workers: decide where they run (<code>serve</code>, or <code>queue:work</code> processes with <code>queue.enabled = false</code> on web instances); clocks synchronized (NTP); <code>queue:failed</code> watched; job payloads and error messages carry no secrets (<a href="./../digging-deeper/queues.html">Queues</a>).</li><li>[ ] The clean-ups of sessions, sign-ins, links and old audit entries (<code>rustcms.auth-prune</code>), of media (<code>rustcms.media-prune.&lt;disk&gt;</code>) and of exports (<code>rustcms.exports-prune.&lt;disk&gt;</code>) run only in <code>serve</code> with <code>[schedule] enabled</code>: keep the scheduler on at least one instance, or cron them (<a href="./../operations/retention.html#from-cron">Data retention</a>).</li></ul><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><ul><li>[ ] S3 storage: a private bucket, credentials limited to it, an <em>abort incomplete multipart uploads</em> lifecycle rule, <code>storage.root</code> writable by the app only (uploads are staged there) (<a href="./../digging-deeper/storage.html">File storage</a>).</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./../getting-started/deployment.html">Deployment</a></li><li><a href="./../getting-started/configuration.html">Configuration</a></li><li><a href="./authentication.html">Authentication</a></li><li><a href="./revocation.html">Credential revocation</a></li><li><a href="./../operations/retention.html">What is kept, and for how long</a></li></ul>',16)])])}const p=t(r,[["render",n]]);export{m as __pageData,p as default};
